import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { categories, projects, inspirationProjects } from '../src/catalog.mjs';
import { config as i18nConfig, enabledLangs, defaultLang, langPrefix, loadDicts, translateHtml, mapProjects } from './i18n.mjs';
const root = new URL('../', import.meta.url);
const source = await readFile(new URL('src/home.html', root), 'utf8');
const reviews = JSON.parse(await readFile(new URL('src/reviews.json',root),'utf8'));
const kitchenGroups = JSON.parse(await readFile(new URL('src/gallery-kitchens.json',root),'utf8'));
const galleryReviewIds = JSON.parse(await readFile(new URL('src/gallery-review-ids.json',root),'utf8'));
// Kanoniskā adrese: SITE_URL (palaišanai: https://laurasmebeles.lv), citādi Vercel produkcijas adrese, citādi lokāli.
const siteUrl = (process.env.SITE_URL || (process.env.VERCEL_PROJECT_PRODUCTION_URL ? `https://${process.env.VERCEL_PROJECT_PRODUCTION_URL}` : 'http://127.0.0.1:4173')).replace(/\/+$/,'');
const siteName = 'Lauras mēbeles';
const dicts = await loadDicts();
const appKeys = [...(await readFile(new URL('public/app.js',root),'utf8')).matchAll(/\bT\((['`])((?:\\.|(?!\1).)*)\1\)/g)].map(m=>m[2]);
const ogImage = { path:'/images/og-default.jpg', width:1200, height:630, alt:'Priekšnama skapis un drēbju pakaramie ar koka latām un dzīvojamo telpu' };
const esc = s => String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const arrow = '<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg>';
const reviewPath = '/virtuves-mebeles-atsauksmes-virtuves-iekartas/';
const section = id => { const start=source.indexOf(`<section id="${id}"`); const end=source.indexOf('</section>',start)+10; if(start<0) throw Error(`Missing section ${id}`); return source.slice(start,end); };
const head = source.slice(0, source.indexOf('<body>'));
const top = source.match(/<div class="topline">[\s\S]*?<\/div>/)[0];
const header = `<a class="skip" href="#saturs">Pāriet uz saturu</a>${top}
<header class="header"><a href="/" class="brand" aria-label="Lauras mēbeles, sākums"><img src="/images/logo.png" alt="Lauras mēbeles" width="171" height="68"></a>
<button class="menu-toggle" aria-label="Atvērt izvēlni" aria-expanded="false" aria-controls="navigation">Izvēlne <span aria-hidden="true">☰</span></button>
<nav id="navigation" aria-label="Galvenā navigācija"><details class="service-menu"><summary>Pakalpojumi</summary><div class="service-submenu"><a href="/pakalpojumi/">Visi pakalpojumi</a>${categories.map(c=>`<a href="/${c.path}/">${esc(c.label)}</a>`).join('')}</div></details><a href="/iedvesmai/">Iedvesmai</a><a href="/musu-darbi/">Mūsu darbi</a><a href="/cenas/">Cenas</a><a href="/par-mums/">Par mums</a><a href="${reviewPath}">Atsauksmes</a><a href="/kontakti/">Kontakti</a><a class="button button-small" href="/kontakti/#pieteikums" data-event="cta_click" data-location="header">Sazināties ar mums ${arrow}</a></nav></header>`;
const footer = source.match(/<footer>[\s\S]*?<\/footer>/)[0].replace('href="#mebeles"','href="/pakalpojumi/"').replace('>Mēbeles</a>','>Pakalpojumi</a>').replace('href="#darbi"','href="/musu-darbi/"').replace('href="#pieteikums"','href="/kontakti/#pieteikums"').replace('<span>Dizaina uzmetums 02 · LV</span>','').replace('<a href="#" aria-label="Lauras mēbeles, uz sākumu">','<a href="/" aria-label="Lauras mēbeles, uz sākumu">').replace(/<details class="event-debug">[\s\S]*?<\/details>/,'').replace(/<div><a href="\/pakalpojumi\/">Pakalpojumi<\/a>[\s\S]*?Sazināties<\/a><\/div>/,'<div><a href="/pakalpojumi/">Pakalpojumi</a><a href="/iedvesmai/">Iedvesmai</a><a href="/musu-darbi/">Mūsu darbi</a><a href="/cenas/">Cenas</a><a href="/par-mums/">Par mums</a><a href="/kontakti/">Kontakti</a></div>');
const dialog = `<dialog id="project-dialog" aria-labelledby="dialog-title"><button class="dialog-close" aria-label="Aizvērt projektu">×</button><img id="dialog-image" alt="" width="1600" height="1067"><div class="photo-controls"><button type="button" id="photo-prev" aria-label="Iepriekšējais foto">←</button><p id="photo-count" aria-live="polite"></p><button type="button" id="photo-next" aria-label="Nākamais foto">→</button></div><div class="dialog-body"><p class="eyebrow">Lauras mēbeļu projekts</p><h2 id="dialog-title"></h2><p id="dialog-description"></p></div></dialog>`;
const cta = (title='Iepatikās kāds no mūsu darbiem?',text='Pastāstiet, kādas mēbeles vēlaties savām mājām.') => `<aside class="project-cta"><div><h2>${esc(title)}</h2><p>${esc(text)}</p></div><a class="button" href="/kontakti/#pieteikums" data-event="cta_click" data-location="gallery">Saņemt cenas piedāvājumu ${arrow}</a></aside>`;
const crumbs = label => `<p class="breadcrumbs"><a href="/">Sākums</a><span>/</span>${esc(label)}</p>`;
const pageIntro = (label,title,text,eyebrow=label,extraClass='') => `<section class="section page-intro${extraClass?` ${extraClass}`:''}">${crumbs(label)}<p class="eyebrow">${esc(eyebrow)}</p><h1>${esc(title)}</h1>${text?`<p>${esc(text)}</p>`:''}</section>`;
const card = p => `<article class="project" data-category="${p.categories.join(' ')}"><button class="project-open" data-project="${p.id}" data-photo="${p.before?1:0}" aria-label="Atvērt projektu: ${esc(p.title)}"><img src="/images/${p.photos[0]}" alt="${esc(p.title)}" width="800" height="600" loading="lazy"><span class="project-zoom" aria-hidden="true">${arrow}</span>${(p.photos.length+(p.before?1:0))>1?`<span class="photo-badge">${p.photos.length+(p.before?1:0)} foto</span>`:''}</button><div class="project-caption"><h3>${esc(p.title)}</h3><p>${esc(p.description)}</p></div></article>`;
const kText = text => { const m=String(text).match(/^(.+?[.!?])\s+([\s\S]+)$/); return m?`<div class="kcase-text"><p>${esc(m[1])}</p><details><summary>Lasīt vairāk</summary><p>${esc(m[2])}</p></details></div>`:`<div class="kcase-text"><p>${esc(text)}</p></div>`; };
const kcase = p => { const shots=p.photos.slice(0,2).map((f,i)=>[f,'',i+(p.before?1:0)]); return `<article class="kcase"><div class="kcase-media">${shots.map(([f,l,i])=>`<figure${l==='Pirms'?' class="is-before"':''}><button class="kcase-open" data-project="${p.id}" data-photo="${i}" aria-label="Atvērt projektu: ${esc(p.title)}${l?', '+l.toLowerCase():''}"><img src="/images/${f}" alt="${esc(p.title)}${l?', '+l.toLowerCase():''}" width="900" height="675" loading="lazy"></button>${l?`<figcaption>${l}</figcaption>`:''}</figure>`).join('')}</div><h3>${esc(p.title)}</h3>${kText(p.description)}</article>`; };
const baItem = (p, heading='h2') => `<article class="ba"><div class="ba-frame" data-ba><img class="ba-after" src="/images/${p.photos[0]}" alt="${esc(p.title)}, pēc" width="900" height="675" loading="lazy"><img class="ba-before" src="/images/${p.before}" alt="${esc(p.title)}, pirms" width="900" height="675" loading="lazy"><span class="ba-tag ba-tag-before">Pirms</span><span class="ba-tag ba-tag-after">Pēc</span><span class="ba-handle" aria-hidden="true"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m9 7-5 5 5 5M15 7l5 5-5 5"/></svg></span><input class="ba-range" type="range" min="0" max="100" value="50" aria-label="Salīdzināt virtuvi pirms un pēc: ${esc(p.title)}"></div><${heading}>${esc(p.title)}</${heading}><button type="button" class="ba-more" data-project="${p.id}" data-photo="0">Skatīt visus foto (${p.photos.length+1})</button></article>`;
const baPage = () => pageIntro('Iedvesmai','Virtuves pirms un pēc','Apskatiet, kā mainījušās klientu virtuves. Pabīdiet attēlu atdalītāju, lai salīdzinātu pirms un pēc.','Iedvesmai')+`<section class="section section-tight inspiration-page"><div class="ba-grid">${[...projects.filter(p=>p.case&&p.before&&p.categories.includes('virtuve')),...inspirationProjects].map(baItem).join('')}</div><div class="gallery-bottom inspiration-gallery-bottom"><a class="nk-button nk-button-outline" href="/musu-darbi/?kategorija=virtuve" data-event="cta_click" data-location="inspiration_gallery">Apskatīt visus virtuves projektus ${arrow}</a></div></section>`;
const kcases = id => `<div class="kcases">${projects.filter(p=>p.case&&p.categories.includes(id)&&p.featured).map(kcase).join('')}</div>`;
import { readFileSync as _rf } from 'node:fs';
const imgSizes = JSON.parse(_rf(new URL('../src/image-sizes.json', import.meta.url), 'utf8'));
// Vecās galerijas secība un pagaidu projektu numuri ir atsevišķā failā.
// Kur vecais kadrs jau ir projektā, attiecīgā grupa papildina esošo ierakstu.
const usedKitchenIds = new Set(kitchenGroups.map(g=>g.existingId).filter(Boolean));
const galleryProjects = [
  ...kitchenGroups.map(g=>{
    const current = g.existingId ? projects.find(p=>p.id===g.existingId) : null;
    if(g.existingId && !current) throw Error(`Galerijas projekts nav atrasts: ${g.existingId}`);
    const photos = [...new Set([...g.photos,...(current?.photos||[])])];
    return { id:current?.id||`archive-${g.sourceGroup.toLowerCase()}`, reviewId:g.reviewId, reviewPoor:!!g.reviewPoor,
      categories:g.categories, title:current?.title||'Virtuves projekts',
      description:current?.description||'', photos, provisional:!current };
  }),
  ...projects.filter(p=>!usedKitchenIds.has(p.id)).map(p=>({ ...p, reviewId:galleryReviewIds[p.id], photos:[...new Set(p.photos)] }))
];
if(galleryProjects.some(p=>!Number.isInteger(p.reviewId)) || new Set(galleryProjects.map(p=>p.reviewId)).size!==galleryProjects.length) throw Error('Galerijas atlases numuri nav pilnīgi vai atkārtojas');
const galleryCard = p => { const f=p.photos[0],s=imgSizes[f]||[900,675],label=p.reviewId?`Projekts ${p.reviewId}`:p.title;
  return `<article class="gallery-project" data-category="${p.categories.join(' ')}"><a href="/musu-darbi/${p.id}/" aria-label="Atvērt projektu: ${esc(label)}; ${p.photos.length} foto"><span class="gallery-project-image"><img src="/images/${esc(f)}" alt="${esc(p.title)}" width="${s[0]}" height="${s[1]}" loading="lazy"><span class="gallery-project-index${p.reviewPoor?' is-low-quality':''}" aria-hidden="true">${p.reviewId}</span><span class="gallery-project-count">${p.photos.length>1?`+${p.photos.length-1} foto`:'1 foto'}</span></span></a></article>`;
};
const galleryGrid = () => `<div class="gallery-projects">${galleryProjects.map(galleryCard).join('')}</div>`;
const galleryLightbox = `<dialog id="lightbox" class="lightbox" aria-label="Foto skats"><button class="lb-close" type="button" aria-label="Aizvērt">×</button><button class="lb-nav lb-prev" type="button" aria-label="Iepriekšējais foto">‹</button><img id="lb-img" alt=""><button class="lb-nav lb-next" type="button" aria-label="Nākamais foto">›</button><p id="lb-count" class="lb-count"></p></dialog>`;
const galleryDetail = p => { const title=`Projekts ${p.reviewId}`;
  const photos=p.photos.map((f,i)=>{const s=imgSizes[f]||[900,675];return `<figure><button class="gphoto-open" type="button" aria-label="Atvērt ${esc(title)} foto ${i+1}"><img src="/images/${esc(f)}" alt="${esc(p.title)}, foto ${i+1}" width="${s[0]}" height="${s[1]}" loading="lazy"></button></figure>`;}).join('');
  return `<section class="section gallery-detail-intro"><p class="breadcrumbs"><a href="/">Sākums</a><span>/</span><a href="/musu-darbi/">Mūsu darbi</a></p><h1 aria-label="${esc(title)}">${p.reviewId}</h1></section><section class="section section-tight gallery-detail-section"><div class="gallery-detail-photos">${photos}</div>${galleryLightbox}<p class="gallery-detail-back"><a class="text-link" href="/musu-darbi/?kategorija=${p.categories[0]}">Visi šīs kategorijas darbi ${arrow}</a></p></section>`;
};
const grid = list => `<div class="projects-grid uniform-grid">${list.map(card).join('')}</div>`;
// Pakalpojumu bloks: virtuves ir galvenais virziens (kolāža), pārējās kategorijas ir saraksts.
// Kolāžas foto izvēlēti tā, lai tie nesakristu ar sākumlapas hero un "Realizētie projekti" foto.
// Kad citai kategorijai būs 3+ foto, tai var pievienot kolāžu tāpat.
const featuredCategory = 'virtuve';
const featuredCollage = ['sala','gaisa','kompakta'];
const categoryCards = () => {
  const feat = categories.find(c=>c.id===featuredCategory);
  const shots = featuredCollage.map(id=>projects.find(p=>p.id===id)).map(p=>({src:p.photos[0],alt:p.title}));
  const rest = categories.filter(c=>c!==feat);
  const collage = shots.map((s,i)=>`<img src="/images/${s.src}" alt="${esc(s.alt)}" width="800" height="${i===0?1000:600}" loading="lazy">`).join('');
  const rows = rest.map(c=>`<li><a href="/${c.path}/" data-event="category_select" data-category="${c.id}"><div class="service-row-text"><h3>${esc(c.label)}</h3><p>${esc(c.short)}</p></div>${arrow}</a></li>`).join('');
  return `<div class="services-layout"><a class="service-feature" href="/${feat.path}/" data-event="category_select" data-category="${feat.id}"><div class="collage">${collage}</div><div class="service-feature-copy"><h3>${esc(feat.label)} ${arrow}</h3><p>${esc(feat.short)}</p></div></a><ul class="service-rows">${rows}</ul></div>`;
};
const reviewById = new Map(reviews.map(r => [r.id,r]));
const selectReviews = ids => ids.map(id => { const review = reviewById.get(id); if (!review) throw Error(`Missing review ${id}`); return review; });
const homeReviewIds = ['google-karlina-gatere','facebook-dace-milberga','web-3'];
const pageReviewIds = [
  'google-karlina-gatere','facebook-dace-milberga','web-3',
  'google-julia-staudza','facebook-erlens-ernstsons','web-2',
  'google-kg-knutsson','facebook-lasma-cerina','web-1',
  'web-4','web-5','web-6'
];
const reviewMeta = r => r.source==='google'
  ? `<div class="review-meta"><span class="review-source"><span class="review-source-icon review-source-icon-google" aria-hidden="true">G</span>Google</span><span class="review-stars" role="img" aria-label="${r.rating} no 5 zvaigznēm">★★★★★</span></div>`
  : r.source==='facebook'
    ? `<div class="review-meta"><span class="review-source"><span class="review-source-icon review-source-icon-facebook" aria-hidden="true">f</span>Facebook</span><span class="review-recommendation">Iesaka Lauras mēbeles</span></div>`
    : `<div class="review-meta"><span class="review-source">Klienta atsauksme</span></div>`;
const reviewAvatar = `<span class="review-avatar" aria-hidden="true"><svg viewBox="0 0 40 40" focusable="false"><circle cx="20" cy="14" r="6"/><path d="M8 34c0-7 5-11 12-11s12 4 12 11"/></svg></span>`;
const reviewCard = r => {
  const text = r.text.replace(/[\u2013\u2014]/g,'-');
  const sentenceEnd = [...text.matchAll(/[.!?](?=\s|$)/g)].map(m=>m.index+1).find(pos=>pos>=120&&pos<=220);
  const cut = text.length>230 ? (sentenceEnd || text.lastIndexOf(' ',200)) : 0;
  const head = cut>0?text.slice(0,cut).trimEnd():text;
  const rest = cut>0?text.slice(cut).trimStart():'';
  return `<article class="review-card" data-review-source="${r.source}"><div class="review-bubble">${reviewMeta(r)}<blockquote>${rest?`<p class="rm"><span class="rm-head">${esc(head)}</span><span class="rm-dots" aria-hidden="true"> …</span><span class="rm-tail" hidden> ${esc(rest)}</span> <button type="button" class="rm-btn" aria-expanded="false">Lasīt vairāk</button></p>`:`<p>${esc(text)}</p>`}</blockquote></div><p class="review-author">${reviewAvatar}<span>${esc(r.author)}</span></p></article>`;
};
const reviewGrid = list => `<div class="review-grid">${list.map(reviewCard).join('')}</div>`;
const homeServices = `<section id="mebeles" class="section"><div class="section-heading"><div><p class="eyebrow">01 / Pakalpojumi</p><h2>Ko mēs izgatavojam?</h2></div><p>No virtuves līdz garderobei. Mēbeles, kas iederas jūsu mājās.</p></div>${categoryCards()}</section>`;
const homeProjects = `<section id="darbi" class="section projects-section"><div class="section-heading"><div><p class="eyebrow">02 / Realizētie projekti</p><h2>Iedvesma jūsu mājām.</h2></div><p>Virtuves, skapji un pārdomāti risinājumi īstās mājās.</p></div>${grid(['peleka','skapis','prieksnams'].map(id=>projects.find(p=>p.id===id)))}<div class="gallery-bottom"><a class="text-link" href="/musu-darbi/">Visi mūsu darbi ${arrow}</a></div></section>`;
const homeReviews = `<section id="atsauksmes" class="section reviews-section"><div class="section-heading"><div><p class="eyebrow">Klientu pieredze</p><h2>Ko saka mūsu klienti</h2></div><a class="text-link" href="${reviewPath}">Visas atsauksmes ${arrow}</a></div>${reviewGrid(selectReviews(homeReviewIds))}</section>`;
let home = source.slice(source.indexOf('<main id="saturs">')+18,source.indexOf('</main>'));
home=home.replace(section('mebeles'),homeServices).replace(section('darbi'),homeProjects);
const homePrice=`<section id="cenas" class="section home-price"><div class="home-price-box"><div><p class="eyebrow">Cenas</p><h2>Cik maksās jūsu mēbeles?</h2><p>Apskatiet virtuvju cenu piemērus vai pastāstiet par savu ieceri, un sagatavosim individuālu piedāvājumu. Cenā ietveram projektēšanu, piegādi un montāžu.</p></div><div class="home-price-actions"><a class="button" href="/cenas/">Apskatīt cenu piemērus</a><a class="text-link" href="/kontakti/#pieteikums">Pieteikt konsultāciju ${arrow}</a></div></div></section>`;
const homeProcess=`<section id="process" class="section home-process"><div class="section-heading"><div><p class="eyebrow">Kā mēs strādājam</p><h2>No sarunas<br>līdz montāžai</h2></div><p>Pietiek ar ideju. Pārējo izplānosim kopā.</p></div><ol class="process-short"><li>Konsultācija</li><li>Uzmērīšana</li><li>3D projekts</li><li>Tāme un līgums</li><li>Ražošana</li><li>Montāža</li></ol><div class="gallery-bottom"><a class="text-link" href="/par-mums/">Kā noris process ${arrow}</a></div></section>`;
home=home.replace(section('cenas'),homePrice).replace(section('process'),homeProcess).replace(section('jautajumi'),'');
const tile=(href,img,label,alt,ev='',size=[1200,800])=>`<a class="nk-tile" href="${href}"${ev}><img src="${img.startsWith('/')?img:`/images/home/${img}.webp`}" alt="${esc(alt)}" width="${size[0]}" height="${size[1]}" loading="lazy"><span class="nk-tile-label">${esc(label)}</span></a>`;
const nkHero=`<section class="nk-hero" aria-label="Lauras mēbeles" data-hero><div class="nk-hero-slides"><picture><source media="(max-width:760px)" srcset="/images/home/hero-3m.webp"><img class="is-active" src="/images/home/hero-3.webp" alt="Melna virtuve ar stikla vitrīnām, koka toņa virsmu un apaļu ēdamgaldu" width="1254" height="702" fetchpriority="high"></picture><img src="/images/home/hero-2.webp" alt="Virtuve bēšos toņos ar akmens raksta sienas paneli un dzīvojamo zonu" width="2000" height="1335" loading="eager"><img src="/images/virtuves/gaisa-stura-virtuve-ar-ramja-fasadem-3.webp" alt="Gaišas virtuves detaļas ar rāmja fasādēm un misiņa toņa izlietni" width="1400" height="1050" loading="eager"></div><div class="nk-hero-copy"><p class="nk-hero-since">ANNO 2008</p><h1>Virtuves un citas mēbeles<span class="nk-hero-break"><br></span> pēc pasūtījuma</h1><div class="nk-hero-actions"><a class="nk-button" href="/virtuves/" data-event="cta_click" data-location="hero">Apskatīt virtuves</a><a class="nk-button nk-button-ghost" href="/kontakti/#pieteikums" data-event="cta_click" data-location="hero">Sazināties</a></div></div><button class="nk-hero-pause" type="button" aria-label="Apturēt bilžu maiņu" data-hero-pause><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path class="nk-hero-icon-pause" d="M9 6v12m6-12v12" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"/><path class="nk-hero-icon-play" d="m9 6 9 6-9 6z" fill="currentColor"/></svg></button></section>`;
